<template>
  <el-container>
    <el-header class="app-header"><AsideVue/></el-header>
    <el-main class="main-ctx monitor-page">
      <div class="page-heading">
        <div><h2>学生答题行为记录</h2><p>整合答题成绩、切屏等行为异常，以及摄像头截图的手机检测结果。</p></div>
        <el-button :loading="loading" @click="load"><el-icon><Refresh/></el-icon>刷新数据</el-button>
      </div>
      <el-alert class="ai-tip" type="warning" :closable="false" show-icon title="AI 手机检测仅用于风险初筛；“疑似手机搜题”必须结合原始截图和行为事件由教师复核，不能单独作为作弊结论。"/>

      <el-row :gutter="16" class="summary-row">
        <el-col :span="6"><el-card shadow="never"><div class="metric"><span>监测学生</span><strong>{{ summary.student_count||0 }}</strong></div></el-card></el-col>
        <el-col :span="6"><el-card shadow="never"><div class="metric"><span>行为异常</span><strong>{{ summary.event_count||0 }}</strong></div></el-card></el-col>
        <el-col :span="6"><el-card shadow="never"><div class="metric"><span>监控照片</span><strong>{{ summary.snapshot_count||0 }}</strong></div></el-card></el-col>
        <el-col :span="6"><el-card shadow="never"><div class="metric risk"><span>疑似手机搜题照片</span><strong>{{ summary.suspected_count||0 }}</strong></div></el-card></el-col>
      </el-row>

      <el-card shadow="never">
        <el-form :model="query" inline>
          <el-form-item label="学生账号"><el-input v-model="query.username" clearable/></el-form-item>
          <el-form-item label="章节"><el-input v-model="query.chapter" clearable/></el-form-item>
          <el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item>
        </el-form>
        <el-table :data="rows" border stripe v-loading="loading">
          <el-table-column prop="username" label="学生" min-width="110"/>
          <el-table-column label="测验" min-width="150"><template #default="s">第 {{ s.row.chapter }} 章 · {{ s.row.subchapter }}</template></el-table-column>
          <el-table-column label="成绩" width="90" align="center"><template #default="s">{{ s.row.score ?? '未提交' }}</template></el-table-column>
          <el-table-column prop="event_count" label="行为异常" width="100" align="center"/>
          <el-table-column prop="snapshot_count" label="监控照片" width="100" align="center"/>
          <el-table-column label="AI手机检测" width="155" align="center"><template #default="s"><el-tag :type="s.row.suspected_count?'danger':'success'">{{ s.row.suspected_count?`疑似 ${s.row.suspected_count} 张`:'未发现' }}</el-tag></template></el-table-column>
          <el-table-column label="最高置信度" width="110" align="center"><template #default="s">{{ percent(s.row.max_phone_confidence) }}</template></el-table-column>
          <el-table-column label="风险" width="90" align="center"><template #default="s"><el-tag :type="riskType(s.row.risk_level)">{{ riskText(s.row.risk_level) }}</el-tag></template></el-table-column>
          <el-table-column prop="last_activity_time" label="最近活动" min-width="170"/>
          <el-table-column label="操作" width="100" fixed="right"><template #default="s"><el-button text type="primary" @click="openDetail(s.row)">查看证据</el-button></template></el-table-column>
        </el-table>
        <el-pagination class="pagination" v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" layout="total, sizes, prev, pager, next" @change="load"/>
      </el-card>

      <el-drawer v-model="drawer" title="答题监控证据" size="64%">
        <div v-if="selected" class="detail-title">{{ selected.username }} · 第 {{ selected.chapter }} 章 {{ selected.subchapter }}</div>
        <el-tabs>
          <el-tab-pane :label="`行为异常 (${detail.events.length})`">
            <el-timeline><el-timeline-item v-for="event in detail.events" :key="event.id" :timestamp="event.occurred_time" type="warning"><strong>{{ eventLabel(event.event_type) }}</strong><div class="event-detail">{{ event.event_detail }}</div></el-timeline-item></el-timeline>
            <el-empty v-if="!detail.events.length" description="没有行为异常记录"/>
          </el-tab-pane>
          <el-tab-pane :label="`监控照片 (${detail.snapshots.length})`">
            <div class="snapshot-grid">
              <el-card v-for="shot in detail.snapshots" :key="shot.id" shadow="hover" :class="{suspected:shot.phone_detected}">
                <el-image :src="`data:image/jpeg;base64,${shot.image_base64}`" fit="cover" class="snapshot" :preview-src-list="imageList"/>
                <div class="shot-meta"><el-tag size="small" :type="shot.phone_detected?'danger':shot.ai_status==='error'?'warning':'success'">{{ shot.phone_detected?'疑似手机搜题':shot.ai_status==='error'?'分析失败':'未发现手机' }}</el-tag><span>{{ shot.created_time }}</span></div>
                <p>{{ shot.ai_reason }}</p><small>置信度：{{ percent(shot.phone_confidence) }} · 人数：{{ shot.person_count }}</small>
              </el-card>
            </div>
            <el-empty v-if="!detail.snapshots.length" description="没有监控照片"/>
          </el-tab-pane>
        </el-tabs>
      </el-drawer>
    </el-main>
  </el-container>
</template>

<script>
import axios from 'axios'
import AsideVue from '@/components/AsideVue.vue'
export default{
  name:'ExamMonitor',components:{AsideVue},data:()=>({loading:false,rows:[],total:0,summary:{},query:{username:'',chapter:'',pageNum:1,pageSize:20},drawer:false,selected:null,detail:{events:[],snapshots:[]}}),
  computed:{imageList(){return this.detail.snapshots.map(s=>`data:image/jpeg;base64,${s.image_base64}`)}},created(){this.load()},methods:{
    async load(){this.loading=true;try{const {data}=await axios.get('/api/exam/monitor',{params:this.query});this.rows=data.rows||[];this.total=data.total||0;this.summary=data.summary||{}}catch(e){this.$message.error(e.response?.data?.message||'答题监测数据加载失败')}finally{this.loading=false}},
    search(){this.query.pageNum=1;this.load()},reset(){this.query={username:'',chapter:'',pageNum:1,pageSize:20};this.load()},
    async openDetail(row){this.selected=row;this.drawer=true;this.detail={events:[],snapshots:[]};try{const {data}=await axios.get('/api/exam/monitor/detail',{params:{username:row.username,chapter:row.chapter,subchapter:row.subchapter}});this.detail=data}catch(e){this.$message.error('证据详情加载失败')}},
    percent(v){return `${(Number(v||0)*100).toFixed(1)}%`},riskText(v){return {high:'高风险',medium:'需关注',normal:'正常'}[v]||'正常'},riskType(v){return {high:'danger',medium:'warning',normal:'success'}[v]||'success'},
    eventLabel(v){return {page_hidden:'页面切换',window_blur:'窗口失焦',mouse_leave:'鼠标离开',context_menu:'右键操作',screenshot_key:'截屏操作',forbidden_shortcut:'受限快捷键',developer_tools:'开发者工具'}[v]||v}
  }
}
</script>

<style scoped>
.app-header{margin-top:4px;padding:0}.monitor-page{background:#f5f7fb}.page-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.page-heading h2{margin:0;color:#26384d}.page-heading p{margin:6px 0 0;color:#8290a3;font-size:13px}.ai-tip,.summary-row{margin-bottom:16px}.metric span,.metric strong{display:block}.metric span{font-size:13px;color:#8a98aa}.metric strong{font-size:24px;color:#26384d;margin-top:7px}.metric.risk strong{color:#d64b4b}.pagination{margin-top:18px;justify-content:flex-end}.detail-title{font-weight:600;font-size:16px;margin-bottom:12px}.event-detail{color:#69788b;margin-top:5px}.snapshot-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.snapshot-grid .suspected{border-color:#f3aaaa}.snapshot{width:100%;height:230px;background:#eef2f6}.shot-meta{display:flex;align-items:center;justify-content:space-between;margin-top:10px;color:#8995a5;font-size:12px}.snapshot-grid p{font-size:13px;color:#566579;margin:9px 0}.snapshot-grid small{color:#8b97a6}@media(max-width:900px){.snapshot-grid{grid-template-columns:1fr}}
</style>
